pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }

    function testFuzz_property(address recipient1, address recipient2, uint256 amount) public {
        vm.assume(recipient1 != address(0));
        vm.assume(recipient2 != address(0));
        vm.assume(recipient1 != recipient2);

        c.newGrantProposal(recipient1, amount);
        c.newGrantProposal(recipient2, amount);

        (address r1, ) = c.mapPID_grant(1);
        (address r2, uint256 a2) = c.mapPID_grant(2);

        assertTrue(r1 == recipient1 && r2 == recipient2 && a2 == amount);
    }
}
